% ------------------------------------------------------------------
% Module O2 — § 4  Einstein–Hilbert Action & Emergent Dynamics
% ------------------------------------------------------------------
% Replace the hard-wired Newton coupling by the filament scale ℓ_f
% so that no new dimensional constant enters the theory.
% (Original text in fileciteturn32file2.)

\paragraph{Einstein–Hilbert sector (revised).}
The purely geometric contribution to the emergent action is now written  
\begin{equation}
  S_{\text{grav}}
  \;=\;
  \frac{1}{2\kappa}
  \int \! d^{4}x\,
  \sqrt{-g(x)}\;
  R(x),
  \qquad
  \boxed{\kappa \;=\; 8\pi\,\ell_{f}^{2}},
  \label{eq:SAT_EH_action}
\end{equation}
where the {\em transverse filament scale}  
\(
\ell_{f}=(2A/T)^{1/3}
\)
was fixed in Module O0.  
Because $[\kappa]=\text{length}^{2}$, the replacement preserves the correct
mass-dimension of the action without importing an external Newton constant~$G$.

\medskip
Varying \eqref{eq:SAT_EH_action} together with the matter term  
\(S_{\text{mat}}=\int d^{4}x\,\sqrt{-g}\,\mathcal{L}_{\text{mat}}\)  
yields the field equations
\begin{equation}
  R_{\mu\nu}
  \;-\;
  \tfrac12\,g_{\mu\nu}R
  \;=\;
  8\pi\,\ell_{f}^{2}\,
  T_{\mu\nu},
  \label{eq:SAT_EH_field_eqs}
\end{equation}
with the emergent stress–energy tensor  
\(T_{\mu\nu}(x)=\langle E_{\text{vib}}(x),L_{\text{link}}(x)\rangle_{F}\)  
defined earlier.  All downstream appearances of $G$ or the old
\(\kappa=8\pi G/c^{4}\) must therefore be replaced by
\(\ell_{f}^{2}\) according to
\[
  \frac{G}{c^{4}}
  \;\longrightarrow\;
  \ell_{f}^{2}.
\]

